-- Contracting-period completion controls: procurement events, questions, amendments,
-- document versions, CLIN/task-order structures, closeout and renewal workflows.
create table if not exists public.dd_contract_procurement_events (id uuid primary key default gen_random_uuid(), opportunity_id uuid references public.dd_contract_opportunities(id) on delete cascade, buyer_id uuid references public.dd_contract_buyers(id) on delete set null, event_type text not null, event_status text not null default 'OPEN', event_number text, event_title text, procurement_method text, source_url text, issue_date timestamptz, response_deadline timestamptz, award_date timestamptz, notes text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.dd_contract_solicitation_questions (id uuid primary key default gen_random_uuid(), solicitation_id uuid not null references public.dd_contract_solicitations(id) on delete cascade, question_number integer, submitted_at timestamptz, submitted_by uuid references auth.users(id), question_text text not null, buyer_response text, response_at timestamptz, status text not null default 'DRAFT', source_document_ref text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.dd_contract_amendments (id uuid primary key default gen_random_uuid(), solicitation_id uuid not null references public.dd_contract_solicitations(id) on delete cascade, amendment_number text not null, issued_at timestamptz, effective_at timestamptz, title text, summary text, changes text, document_ref text, deadline_changed_to timestamptz, acknowledged_at timestamptz, acknowledged_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(solicitation_id,amendment_number));
create table if not exists public.dd_contract_documents (id uuid primary key default gen_random_uuid(), opportunity_id uuid references public.dd_contract_opportunities(id) on delete cascade, solicitation_id uuid references public.dd_contract_solicitations(id) on delete cascade, proposal_id uuid references public.dd_contract_proposals(id) on delete cascade, contract_id uuid references public.dd_contracts(id) on delete cascade, document_type text not null, document_name text not null, version_number integer not null default 1, document_ref text, source_url text, is_current boolean not null default true, uploaded_by uuid references auth.users(id), uploaded_at timestamptz not null default now(), notes text, metadata jsonb not null default '{}'::jsonb);
create table if not exists public.dd_contract_line_items (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.dd_contracts(id) on delete cascade, line_type text not null default 'CLIN', line_number text not null, description text not null, quantity numeric, unit text, unit_price numeric, ceiling_amount numeric, funded_amount numeric, period_start date, period_end date, option_year integer, status text not null default 'ACTIVE', metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(contract_id,line_number));
create table if not exists public.dd_contract_task_orders (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.dd_contracts(id) on delete cascade, task_order_number text not null, title text not null, issuing_buyer text, issue_date date, start_date date, end_date date, ceiling_value numeric, funded_value numeric, status text not null default 'ACTIVE', scope_summary text, deliverables jsonb not null default '[]'::jsonb, document_refs jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(contract_id,task_order_number));
create table if not exists public.dd_contract_closeouts (id uuid primary key default gen_random_uuid(), contract_id uuid not null unique references public.dd_contracts(id) on delete cascade, closeout_status text not null default 'OPEN', target_closeout_date date, final_deliverables_verified boolean not null default false, final_compliance_verified boolean not null default false, final_invoice_verified boolean not null default false, property_return_verified boolean not null default false, final_performance_recorded boolean not null default false, buyer_acceptance_verified boolean not null default false, closeout_documents jsonb not null default '[]'::jsonb, closeout_notes text, closed_at timestamptz, closed_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.dd_contract_renewals (id uuid primary key default gen_random_uuid(), contract_id uuid not null references public.dd_contracts(id) on delete cascade, renewal_type text not null default 'OPTION', target_date date, decision_deadline date, status text not null default 'OPEN', strategy text, expansion_opportunities jsonb not null default '[]'::jsonb, owner_user_id uuid references auth.users(id), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.dd_contract_awards add column if not exists obligated_value numeric;
alter table public.dd_contracts add column if not exists obligated_value numeric;
alter table public.dd_contracts add column if not exists owner_user_id uuid references auth.users(id);
alter table public.dd_contracts add column if not exists closeout_status text not null default 'OPEN';
alter table public.dd_contracts add column if not exists last_performance_review_date date;
create index if not exists idx_dd_contract_procurement_events_opportunity on public.dd_contract_procurement_events(opportunity_id,event_status,response_deadline);
create index if not exists idx_dd_contract_questions_solicitation on public.dd_contract_solicitation_questions(solicitation_id,status);
create index if not exists idx_dd_contract_amendments_solicitation on public.dd_contract_amendments(solicitation_id,issued_at desc);
create index if not exists idx_dd_contract_documents_current on public.dd_contract_documents(document_type,is_current);
create index if not exists idx_dd_contract_line_items_contract on public.dd_contract_line_items(contract_id,status);
create index if not exists idx_dd_contract_task_orders_contract on public.dd_contract_task_orders(contract_id,status);
create index if not exists idx_dd_contract_renewals_date on public.dd_contract_renewals(contract_id,target_date,status);
alter table public.dd_contract_procurement_events enable row level security;
alter table public.dd_contract_solicitation_questions enable row level security;
alter table public.dd_contract_amendments enable row level security;
alter table public.dd_contract_documents enable row level security;
alter table public.dd_contract_line_items enable row level security;
alter table public.dd_contract_task_orders enable row level security;
alter table public.dd_contract_closeouts enable row level security;
alter table public.dd_contract_renewals enable row level security;
create policy dd_contract_procurement_events_staff_all on public.dd_contract_procurement_events for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
create policy dd_contract_questions_staff_all on public.dd_contract_solicitation_questions for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
create policy dd_contract_amendments_staff_all on public.dd_contract_amendments for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
create policy dd_contract_documents_staff_all on public.dd_contract_documents for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
create policy dd_contract_line_items_staff_all on public.dd_contract_line_items for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
create policy dd_contract_task_orders_staff_all on public.dd_contract_task_orders for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
create policy dd_contract_closeouts_staff_all on public.dd_contract_closeouts for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
create policy dd_contract_renewals_staff_all on public.dd_contract_renewals for all to authenticated using (public.dd_contract_staff_access()) with check (public.dd_contract_staff_access());
